INSERT INTO `library_category_translations` (`id`, `category_id`, `language_id`, `name`, `description`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 'ادبیات', 'کتاب‌های ادبی شامل رمان، شعر، داستان کوتاه و آثار ادبی', 'ادبیات | کتاب‌های شعر، داستان و رمان | کتابخانه دیجیتال', 'مجموعه جامع کتاب‌های ادبیات فارسی و جهان شامل شعر، داستان، رمان و نقد ادبی. دسترسی به آثار کلاسیک و معاصر از بزرگان ادبیات ایران و جهان. مناسب برای علاقه‌مندان، دانشجویان و پژوهشگران ادبیات.', '2025-05-12 01:56:02', '2025-05-12 02:15:24'),
(2, 2, 1, 'آموزشی و کمک درسی', 'کتاب‌های درسی و کمک آموزشی برای دانش‌آموزان و معلمان', 'کتاب‌های آموزشی و کمک درسی | منابع درسی تخصصی | کتابخانه دیجیتال', 'مجموعه کامل کتاب‌های آموزشی و کمک درسی برای تمامی پایه‌های تحصیلی و رشته‌ها. منابع تخصصی برای دانش‌آموزان، دانشجویان و معلمان با هدف تقویت مهارت‌های علمی و آموزشی.', '2025-05-12 01:56:02', '2025-05-12 02:15:24'),
(3, 3, 1, 'داستان', 'انواع مختلف کتاب‌های داستانی', 'کتاب‌های داستان | داستان کوتاه و بلند ایرانی و خارجی | کتابخانه دیجیتال', 'گنجینه‌ای از داستان‌های کوتاه و بلند از نویسندگان برجسته ایرانی و خارجی. دسترسی به آثار داستانی در ژانرهای مختلف برای همه سنین و سلیقه‌ها. لذت مطالعه آثار داستانی برتر در کتابخانه دیجیتال.', '2025-05-12 01:56:02', '2025-05-12 02:15:24'),
(4, 4, 1, 'شعر', 'مجموعه‌های شعر از شاعران کلاسیک و معاصر', 'شعر | دیوان و مجموعه اشعار کلاسیک و معاصر | کتابخانه دیجیتال', 'مجموعه‌ای ارزشمند از اشعار شاعران کلاسیک و معاصر ایران و جهان. دسترسی به دیوان‌های کامل و گزیده اشعار برگزیده. مناسب برای دوستداران شعر، پژوهشگران و دانشجویان ادبیات.', '2025-05-12 01:56:02', '2025-05-12 02:15:24'),
(5, 5, 1, 'علوم انسانی', 'کتاب‌های مرتبط با رشته‌های علوم انسانی', 'کتاب‌های علوم انسانی | منابع تخصصی رشته‌های علوم انسانی | کتابخانه دیجیتال', 'مجموعه تخصصی کتاب‌های حوزه علوم انسانی شامل فلسفه، روانشناسی، جامعه‌شناسی، اقتصاد، علوم سیاسی و سایر رشته‌ها. منابع علمی و کاربردی برای دانشجویان، اساتید و پژوهشگران.', '2025-05-12 01:56:02', '2025-05-12 02:15:24'),
