INSERT INTO `library_publisher_translations` (`id`, `publisher_id`, `language_id`, `name`, `description`, `address`, `contact_info`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 'انتشارات انقلاب اسلامی', 'انتشارات انقلاب اسلامی یکی از ناشران پیشرو در زمینه کتاب‌های مرتبط با انقلاب اسلامی، مبانی اسلامی و تاریخ معاصر ایران است. این انتشارات از سال 1357 فعالیت خود را آغاز کرده و در زمینه انتشار آثار با مضامین دینی، فرهنگی و سیاسی فعالیت می‌کند.', 'تهران، خیابان انقلاب، خیابان ۱۲ فروردین', 'تلفن: 02166490612 - ایمیل: info@enghelaab.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(2, 2, 1, 'نشر مون', 'نشر مون یکی از ناشران پیشرو در زمینه کتاب‌های آموزشی، کمک‌درسی و رفرنس است. این انتشارات با بیش از چهار دهه تجربه، کتاب‌های باکیفیت و معتبری را در حوزه‌های مختلف علمی و آموزشی منتشر کرده است.', 'تهران، خیابان انقلاب، نرسیده به پل چوبی', 'تلفن: 02166960201 - ایمیل: info@moon.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(3, 3, 1, 'نشر ملیکان', 'نشر ملیکان از ناشران برجسته در زمینه کتاب‌های علمی، فرهنگی و آموزشی است. این انتشارات با رویکردی نوین به نشر کتاب، در راستای ارتقای سطح دانش و فرهنگ جامعه گام برمی‌دارد.', 'تهران، خیابان انقلاب، خیابان شهید موسوی', 'تلفن: 02166490723 - ایمیل: info@mellicanbook.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(4, 4, 1, 'نشر ققنوس', 'نشر ققنوس یکی از معتبرترین ناشران در زمینه ادبیات داستانی، شعر معاصر و ترجمه آثار برجسته جهان است. این انتشارات با بیش از سه دهه فعالیت، نقش مهمی در معرفی آثار ارزشمند ادبی به جامعه فارسی‌زبان داشته است.', 'تهران، خیابان انقلاب، روبروی دانشگاه تهران', 'تلفن: 02166415587 - ایمیل: info@qoqnoos.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(5, 5, 1, 'انتشارات ترجمان', 'انتشارات ترجمان از پیشگامان عرصه ترجمه و نشر کتاب‌های خارجی در ایران است. این انتشارات با بیش از چهار دهه تجربه، آثار برجسته جهانی را با ترجمه‌های دقیق و روان به خوانندگان فارسی‌زبان معرفی کرده است.', 'تهران، میدان انقلاب، خیابان کارگر شمالی', 'تلفن: 02166719080 - ایمیل: info@tarjoman.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(6, 6, 1, 'انتشارات دنیای اقتصاد', 'انتشارات دنیای اقتصاد ناشر تخصصی کتاب‌های اقتصادی، مدیریتی و بازرگانی است. این انتشارات وابسته به روزنامه دنیای اقتصاد، مرجعی معتبر برای علاقه‌مندان به مباحث اقتصادی و کسب‌وکار محسوب می‌شود.', 'تهران، خیابان فردوسی، خیابان شهید گمنام', 'تلفن: 02188912159 - ایمیل: info@donya-e-eqtesad.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(7, 7, 1, 'انتشارات صدرا', 'انتشارات صدرا ناشر تخصصی آثار استاد شهید مرتضی مطهری و کتب مرتبط با فلسفه و عرفان اسلامی است. این انتشارات با هدف ترویج اندیشه‌های اسلامی و پاسخگویی به نیازهای فکری و فرهنگی جامعه فعالیت می‌کند.', 'تهران، خیابان انقلاب، خیابان شهید مطهری', 'تلفن: 02166976120 - ایمیل: info@sadrapub.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(8, 8, 1, 'انتشارات اسراء', 'انتشارات اسراء با محوریت نشر آثار آیت‌الله بهشتی و دیگر علمای اسلامی فعالیت می‌کند. این انتشارات در زمینه کتب اسلامی، فلسفی و عرفانی آثار ارزشمندی را به جامعه علمی و فرهنگی کشور ارائه کرده است.', 'قم، خیابان آیت‌الله بروجردی', 'تلفن: 02532800915 - ایمیل: info@esraapub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(9, 9, 1, 'انتشارات نیلوفر', 'انتشارات نیلوفر از برجسته‌ترین ناشران ادبیات داستانی و شعر معاصر در ایران است. این انتشارات با انتخاب و نشر آثار برگزیده ادبی ایران و جهان، در ارتقای سطح ادبیات و فرهنگ جامعه نقش به‌سزایی داشته است.', 'تهران، خیابان انقلاب، خیابان فلسطین شمالی', 'تلفن: 02166971061 - ایمیل: info@nilouferpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(10, 10, 1, 'انتشارات گوتنبرگ', 'انتشارات گوتنبرگ با تمرکز بر ترجمه و نشر آثار کلاسیک جهانی و ادبیات روسی، خدمات ارزنده‌ای به جامعه فرهنگی ایران ارائه کرده است. این انتشارات با انتخاب مترجمان برجسته، کیفیت بالایی از ترجمه را به مخاطبان عرضه می‌کند.', 'تهران، خیابان انقلاب، نرسیده به میدان فردوسی', 'تلفن: 02166411792 - ایمیل: info@gutenbergpub.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(11, 11, 1, 'انتشارات فرزان روز', 'انتشارات فرزان روز با تمرکز بر آثار فروغ فرخزاد و شعر و ادبیات معاصر فارسی، جایگاه ویژه‌ای در فضای فرهنگی ایران دارد. این انتشارات به واسطه انتخاب‌های دقیق و کیفیت بالای آثار منتشر شده، مورد اقبال مخاطبان جدی ادبیات قرار گرفته است.', 'تهران، خیابان انقلاب، خیابان شهید مفتح', 'تلفن: 02166493657 - ایمیل: info@farzanrooz.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(12, 12, 1, 'انتشارات آگاه', 'انتشارات آگاه با بیش از چهار دهه فعالیت، از پیشگامان نشر آثار روشنفکری و ادبیات معاصر در ایران است. این انتشارات که آثار جلال آل احمد و بسیاری از نویسندگان برجسته ایرانی را منتشر کرده، نقش مهمی در تحولات فکری و فرهنگی جامعه ایران داشته است.', 'تهران، خیابان انقلاب، میدان فردوسی', 'تلفن: 02166492314 - ایمیل: info@agahpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(13, 13, 1, 'انتشارات روزنه', 'انتشارات روزنه با تمرکز بر ترجمه و نشر آثار داستایوفسکی و دیگر نویسندگان برجسته روسی، خدمت شایانی به ادبیات ترجمه در ایران کرده است. این انتشارات با ارائه ترجمه‌های دقیق و روان، از محبوبیت خاصی میان علاقه‌مندان به ادبیات روسیه برخوردار است.', 'تهران، خیابان انقلاب، نرسیده به میدان فردوسی', 'تلفن: 02166977420 - ایمیل: info@rozanehpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(14, 14, 1, 'انتشارات نگاه', 'انتشارات نگاه از ناشران معتبر و پیشرو در زمینه آثار فلسفی، عرفانی و کتب تاریخی است. این انتشارات با انتخاب‌های دقیق و کیفیت بالای چاپ و نشر، جایگاه ویژه‌ای میان مخاطبان جدی کتاب در ایران دارد.', 'تهران، میدان انقلاب، خیابان کارگر جنوبی', 'تلفن: 02166719103 - ایمیل: info@negahpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(15, 15, 1, 'انتشارات هرمس', 'انتشارات هرمس از ناشران برجسته در زمینه ترجمه آثار کلاسیک جهانی و فلسفه غرب است. این انتشارات با تمرکز بر کیفیت ترجمه و انتخاب آثار ارزشمند جهانی، نقش مهمی در معرفی اندیشه‌های فلسفی و آثار ادبی برجسته به مخاطبان فارسی‌زبان داشته است.', 'تهران، خیابان انقلاب، خیابان دانشگاه', 'تلفن: 02166490886 - ایمیل: info@hermespub.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(16, 16, 1, 'انتشارات سخن', 'انتشارات سخن از معتبرترین ناشران در حوزه ادبیات کلاسیک فارسی، شعر و نقد ادبی است. این انتشارات با ارائه تصحیح‌های علمی از متون کهن فارسی و انتشار پژوهش‌های ادبی ارزشمند، خدمات شایانی به فرهنگ و ادب ایران کرده است.', 'تهران، خیابان انقلاب، خیابان فخر رازی', 'تلفن: 02166972497 - ایمیل: info@sokhanpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(17, 1, 2, 'Enghelab Eslami Publications', 'Enghelab Eslami Publications is a leading publisher in the field of books related to the Islamic Revolution, Islamic fundamentals, and contemporary Iranian history. This publishing house has been active since 1979 and publishes works with religious, cultural, and political themes.', 'Tehran, Enghelab Street, 12 Farvardin Street', 'Phone: +98 21 66490612 - Email: info@enghelaab.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(18, 2, 2, 'Moon Publications', 'Moon Publications is a leading publisher in the field of educational books, textbooks, and references. With over four decades of experience, this publishing house has published high-quality and reliable books in various scientific and educational fields.', 'Tehran, Enghelab Street, near Choubi Bridge', 'Phone: +98 21 66960201 - Email: info@moon.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(19, 3, 2, 'Mellican Publications', 'Mellican Publications is a prominent publisher of scientific, cultural, and educational books. With a modern approach to book publishing, this publishing house works towards enhancing knowledge and culture in society.', 'Tehran, Enghelab Street, Shahid Mousavi Street', 'Phone: +98 21 66490723 - Email: info@mellicanbook.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(20, 4, 2, 'Qoqnoos Publications', 'Qoqnoos Publications is one of the most respected publishers in the field of fiction, contemporary poetry, and translation of world literary masterpieces. With over three decades of activity, it has played an important role in introducing valuable literary works to Persian-speaking readers.', 'Tehran, Enghelab Street, opposite Tehran University', 'Phone: +98 21 66415587 - Email: info@qoqnoos.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(21, 5, 2, 'Tarjoman Publications', 'Tarjoman Publications is a pioneer in translating and publishing foreign books in Iran. With more than four decades of experience, this publishing house has introduced prominent global works with accurate and fluent translations to Persian-speaking readers.', 'Tehran, Enghelab Square, North Kargar Street', 'Phone: +98 21 66719080 - Email: info@tarjoman.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(22, 6, 2, 'Donya-e-Eqtesad Publications', 'Donya-e-Eqtesad Publications is a specialized publisher of economic, management, and business books. Affiliated with Donya-e-Eqtesad newspaper, it is a reliable reference for those interested in economic and business topics.', 'Tehran, Ferdowsi Street, Shahid Gomnam Street', 'Phone: +98 21 88912159 - Email: info@donya-e-eqtesad.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(23, 7, 2, 'Sadra Publications', 'Sadra Publications specializes in publishing works by Shahid Morteza Motahhari and books related to Islamic philosophy and mysticism. This publishing house operates with the goal of promoting Islamic thought and responding to the intellectual and cultural needs of society.', 'Tehran, Enghelab Street, Shahid Motahhari Street', 'Phone: +98 21 66976120 - Email: info@sadrapub.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(24, 8, 2, 'Esraa Publications', 'Esraa Publications focuses on publishing works by Ayatollah Beheshti and other Islamic scholars. This publishing house has presented valuable works in Islamic, philosophical, and mystical fields to the scientific and cultural community of the country.', 'Qom, Ayatollah Boroujerdi Street', 'Phone: +98 25 32800915 - Email: info@esraapub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(25, 9, 2, 'Niloufar Publications', 'Niloufar Publications is one of the most prominent publishers of fiction and contemporary poetry in Iran. By selecting and publishing selected literary works from Iran and around the world, this publishing house has played a significant role in elevating the level of literature and culture in society.', 'Tehran, Enghelab Street, North Palestine Street', 'Phone: +98 21 66971061 - Email: info@nilouferpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(26, 10, 2, 'Gutenberg Publications', 'Gutenberg Publications focuses on translating and publishing world classics and Russian literature, providing valuable services to Iran\'s cultural community. This publishing house offers high-quality translations to readers by selecting prominent translators.', 'Tehran, Enghelab Street, near Ferdowsi Square', 'Phone: +98 21 66411792 - Email: info@gutenbergpub.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(27, 11, 2, 'Farzan Rooz Publications', 'Farzan Rooz Publications focuses on the works of Forough Farrokhzad and contemporary Persian poetry and literature, holding a special place in Iran\'s cultural space. This publishing house has gained popularity among serious literature enthusiasts due to its careful selection and high quality of published works.', 'Tehran, Enghelab Street, Shahid Mofateh Street', 'Phone: +98 21 66493657 - Email: info@farzanrooz.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(28, 12, 2, 'Agah Publications', 'Agah Publications, with more than four decades of activity, is one of the pioneers in publishing intellectual works and contemporary literature in Iran. This publishing house, which has published works by Jalal Al-e Ahmad and many prominent Iranian writers, has played an important role in the intellectual and cultural developments of Iranian society.', 'Tehran, Enghelab Street, Ferdowsi Square', 'Phone: +98 21 66492314 - Email: info@agahpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(29, 13, 2, 'Rozaneh Publications', 'Rozaneh Publications, focusing on translating and publishing works by Dostoevsky and other prominent Russian writers, has provided a worthy service to translated literature in Iran. This publishing house is particularly popular among enthusiasts of Russian literature due to its accurate and fluent translations.', 'Tehran, Enghelab Street, near Ferdowsi Square', 'Phone: +98 21 66977420 - Email: info@rozanehpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(30, 14, 2, 'Negah Publications', 'Negah Publications is a credible and leading publisher in the field of philosophical, mystical, and historical books. This publishing house holds a special place among serious book enthusiasts in Iran due to its careful selections and high-quality printing and publishing.', 'Tehran, Enghelab Square, South Kargar Street', 'Phone: +98 21 66719103 - Email: info@negahpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(31, 15, 2, 'Hermes Publications', 'Hermes Publications is a prominent publisher in translating world classics and Western philosophy. By focusing on translation quality and selecting valuable global works, this publishing house has played an important role in introducing philosophical ideas and outstanding literary works to Persian-speaking audiences.', 'Tehran, Enghelab Street, Daneshgah Street', 'Phone: +98 21 66490886 - Email: info@hermespub.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(32, 16, 2, 'Sokhan Publications', 'Sokhan Publications is one of the most credible publishers in the field of classical Persian literature, poetry, and literary criticism. This publishing house has provided valuable services to Iranian culture and literature by offering scientific corrections of ancient Persian texts and publishing valuable literary research.', 'Tehran, Enghelab Street, Fakhr Razi Street', 'Phone: +98 21 66972497 - Email: info@sokhanpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(33, 1, 3, 'منشورات الثورة الإسلامية', 'منشورات الثورة الإسلامية هي دار نشر رائدة في مجال الكتب المتعلقة بالثورة الإسلامية والأسس الإسلامية وتاريخ إيران المعاصر. بدأت هذه الدار نشاطها منذ عام 1979 وتنشر أعمالاً ذات مضامين دينية وثقافية وسياسية.', 'طهران، شارع انقلاب، شارع 12 فروردين', 'هاتف: 02166490612 - بريد إلكتروني: info@enghelaab.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(34, 2, 3, 'منشورات مون', 'منشورات مون هي دار نشر رائدة في مجال الكتب التعليمية والكتب المدرسية والمراجع. مع أكثر من أربعة عقود من الخبرة، نشرت هذه الدار كتباً عالية الجودة وموثوقة في مختلف المجالات العلمية والتعليمية.', 'طهران، شارع انقلاب، بالقرب من جسر جوبي', 'هاتف: 02166960201 - بريد إلكتروني: info@moon.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(35, 3, 3, 'منشورات مليكان', 'منشورات مليكان هي دار نشر بارزة للكتب العلمية والثقافية والتعليمية. بنهج حديث في نشر الكتب، تعمل هذه الدار على تعزيز مستوى المعرفة والثقافة في المجتمع.', 'طهران، شارع انقلاب، شارع الشهيد موسوي', 'هاتف: 02166490723 - بريد إلكتروني: info@mellicanbook.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(36, 4, 3, 'منشورات قوقنوس', 'منشورات قوقنوس هي واحدة من أكثر دور النشر احتراماً في مجال الأدب الروائي والشعر المعاصر وترجمة روائع الأدب العالمي. مع أكثر من ثلاثة عقود من النشاط، لعبت دوراً مهماً في تقديم أعمال أدبية قيمة للقراء الناطقين بالفارسية.', 'طهران، شارع انقلاب، مقابل جامعة طهران', 'هاتف: 02166415587 - بريد إلكتروني: info@qoqnoos.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(37, 5, 3, 'منشورات ترجمان', 'منشورات ترجمان هي من الرواد في ترجمة ونشر الكتب الأجنبية في إيران. مع أكثر من أربعة عقود من الخبرة، قدمت هذه الدار أعمالاً عالمية بارزة بترجمات دقيقة وسلسة للقراء الناطقين بالفارسية.', 'طهران، ميدان انقلاب، شارع كاركر الشمالي', 'هاتف: 02166719080 - بريد إلكتروني: info@tarjoman.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(38, 6, 3, 'منشورات دنيا الاقتصاد', 'منشورات دنيا الاقتصاد هي دار نشر متخصصة في كتب الاقتصاد والإدارة والأعمال. وهي تابعة لصحيفة دنيا الاقتصاد، وتعتبر مرجعاً موثوقاً للمهتمين بالمواضيع الاقتصادية والأعمال التجارية.', 'طهران، شارع فردوسي، شارع الشهيد كمنام', 'هاتف: 02188912159 - بريد إلكتروني: info@donya-e-eqtesad.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(39, 7, 3, 'منشورات صدرا', 'منشورات صدرا هي دار نشر متخصصة في أعمال الشهيد مرتضى مطهري والكتب المتعلقة بالفلسفة والعرفان الإسلامي. تعمل هذه الدار بهدف نشر الفكر الإسلامي والاستجابة للاحتياجات الفكرية والثقافية للمجتمع.', 'طهران، شارع انقلاب، شارع الشهيد مطهري', 'هاتف: 02166976120 - بريد إلكتروني: info@sadrapub.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(40, 8, 3, 'منشورات إسراء', 'منشورات إسراء تركز على نشر أعمال آية الله بهشتي وغيره من العلماء الإسلاميين. قدمت هذه الدار أعمالاً قيمة في المجالات الإسلامية والفلسفية والعرفانية للمجتمع العلمي والثقافي في البلاد.', 'قم، شارع آية الله بروجردي', 'هاتف: 02532800915 - بريد إلكتروني: info@esraapub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(41, 9, 3, 'منشورات نيلوفر', 'منشورات نيلوفر هي واحدة من أبرز دور النشر للأدب الروائي والشعر المعاصر في إيران. من خلال اختيار ونشر الأعمال الأدبية المختارة من إيران والعالم، لعبت هذه الدار دوراً كبيراً في رفع مستوى الأدب والثقافة في المجتمع.', 'طهران، شارع انقلاب، شارع فلسطين الشمالي', 'هاتف: 02166971061 - بريد إلكتروني: info@nilouferpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(42, 10, 3, 'منشورات غوتنبرغ', 'تركز منشورات غوتنبرغ على ترجمة ونشر الكلاسيكيات العالمية والأدب الروسي، مقدمة خدمات قيمة للمجتمع الثقافي في إيران. توفر هذه الدار ترجمات عالية الجودة للقراء من خلال اختيار مترجمين بارزين.', 'طهران، شارع انقلاب، بالقرب من ميدان فردوسي', 'هاتف: 02166411792 - بريد إلكتروني: info@gutenbergpub.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(43, 11, 3, 'منشورات فرزان روز', 'تركز منشورات فرزان روز على أعمال فروغ فرخزاد والشعر والأدب الفارسي المعاصر، وتحتل مكانة خاصة في الفضاء الثقافي الإيراني. اكتسبت هذه الدار شعبية بين عشاق الأدب الجاد بسبب اختياراتها الدقيقة والجودة العالية للأعمال المنشورة.', 'طهران، شارع انقلاب، شارع الشهيد مفتح', 'هاتف: 02166493657 - بريد إلكتروني: info@farzanrooz.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(44, 12, 3, 'منشورات آگاه', 'تعد منشورات آگاه، مع أكثر من أربعة عقود من النشاط، من رواد نشر الأعمال الفكرية والأدب المعاصر في إيران. لعبت هذه الدار، التي نشرت أعمال جلال آل أحمد والعديد من الكتاب الإيرانيين البارزين، دوراً مهماً في التطورات الفكرية والثقافية للمجتمع الإيراني.', 'طهران، شارع انقلاب، ميدان فردوسي', 'هاتف: 02166492314 - بريد إلكتروني: info@agahpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(45, 13, 3, 'منشورات روزنه', 'تركز منشورات روزنه على ترجمة ونشر أعمال دوستويفسكي وغيره من الكتاب الروس البارزين، مقدمة خدمة جديرة بالثناء للأدب المترجم في إيران. تتمتع هذه الدار بشعبية خاصة بين محبي الأدب الروسي بفضل ترجماتها الدقيقة والسلسة.', 'طهران، شارع انقلاب، بالقرب من ميدان فردوسي', 'هاتف: 02166977420 - بريد إلكتروني: info@rozanehpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(46, 14, 3, 'منشورات نگاه', 'منشورات نگاه هي دار نشر موثوقة ورائدة في مجال الكتب الفلسفية والعرفانية والتاريخية. تحتل هذه الدار مكانة خاصة بين عشاق الكتب الجادين في إيران بفضل اختياراتها الدقيقة وجودة الطباعة والنشر العالية.', 'طهران، ميدان انقلاب، شارع كاركر الجنوبي', 'هاتف: 02166719103 - بريد إلكتروني: info@negahpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(47, 15, 3, 'منشورات هرمس', 'منشورات هرمس هي دار نشر بارزة في ترجمة الكلاسيكيات العالمية والفلسفة الغربية. من خلال التركيز على جودة الترجمة واختيار الأعمال العالمية القيمة، لعبت هذه الدار دوراً مهماً في تقديم الأفكار الفلسفية والأعمال الأدبية البارزة للجماهير الناطقة بالفارسية.', 'طهران، شارع انقلاب، شارع دانشگاه', 'هاتف: 02166490886 - بريد إلكتروني: info@hermespub.ir', '2025-05-12 02:41:04', '2025-05-12 02:41:04'),
(48, 16, 3, 'منشورات سخن', 'منشورات سخن هي واحدة من أكثر دور النشر مصداقية في مجال الأدب الفارسي الكلاسيكي والشعر والنقد الأدبي. قدمت هذه الدار خدمات قيمة للثقافة والأدب الإيراني من خلال تقديم تصحيحات علمية للنصوص الفارسية القديمة ونشر أبحاث أدبية قيمة.', 'طهران، شارع انقلاب، شارع فخر رازي', 'هاتف: 02166972497 - بريد إلكتروني: info@sokhanpub.com', '2025-05-12 02:41:04', '2025-05-12 02:41:04');
