INSERT INTO `temp_edu_levels_translations` (`translation_id`, `content_id`, `language_id`, `content_value`, `created_at`, `updated_at`) VALUES
(1, 1, 'fa', 'مقاطع تحصیلی مجتمع سلمان فارسی', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(2, 2, 'fa', 'برنامه آموزشی جامع و پیشرفته، با تمرکز بر پرورش استعدادها و آماده‌سازی دانش‌آموزان برای آینده‌ای درخشان', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(3, 3, 'fa', 'بخش احسان', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(4, 4, 'fa', 'برای دانش‌آموزان با نیازهای ویژه', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(5, 5, 'fa', 'احسان؛ جایی که هر توانایی مسیر خود را پیدا می‌کند', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(6, 6, 'fa', 'از سال 2008، احسان در مجتمع آموزشی سلمان فارسی محیطی گرم و پذیرا برای دانش‌آموزان با نیازهای ویژه فراهم کرده است. با بهره‌گیری از حمایت تخصصی و رویکردی دلسوزانه، ما هر دانش‌آموز را توانمند می‌سازیم تا استعدادهای خود را شکوفا کند و آینده‌ای روشن‌تر بسازد.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(7, 7, 'fa', 'معلمان متخصص', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(8, 8, 'fa', 'تیمی از کارشناسان آموزش و توانبخشی باکیفیت ارائه می‌دهند.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(9, 9, 'fa', 'حمایت جامع', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(10, 10, 'fa', 'تضمین فرصت‌های برابر برای موفقیت هر دانش‌آموز.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(11, 11, 'fa', 'بیشتر بخوانید', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(12, 12, 'fa', 'بخش ابتدایی', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(13, 13, 'fa', 'از پایه‌ای قوی تا موفقیتی درخشان', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(14, 14, 'fa', 'راهنمایی تخصصی و امکانات پیشرفته', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(15, 15, 'fa', 'بخش آموزش ابتدایی (پایه‌های 1 تا 6) شامل دو کلاس در هر پایه است که بر آموزش قوی و برنامه‌های پیشرفته زبانی در عربی و انگلیسی، تدریس‌شده توسط کارشناسان بومی زبان تمرکز دارد. با معلمان باتجربه، روش‌های نوآورانه و کلاس‌های هوشمند، ما تجربه یادگیری جذاب و شخصی‌سازی‌شده‌ای را تضمین می‌کنیم.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(16, 16, 'fa', 'راهنمایی', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(17, 17, 'fa', 'مدرسان بااستعداد، امکانات مدرن و روش‌های پیشرفته', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(18, 18, 'fa', 'دبیرستان (پایه‌های هفتم تا نهم) در مدرسه سلمان فارسی محیطی مدرن با کلاس‌های هوشمند و معلمان متخصص فراهم می‌آورد. هر پایه دو کلاس دارد که با روش‌های تدریس پیشرفته پشتیبانی می‌شود.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(19, 19, 'fa', 'مدرسه برنامه‌های فوق‌برنامه، آزمایشگاه‌های علمی، امکانات ورزشی و رفاهی ارائه می‌دهد تا دانش‌آموزان هم از نظر علمی و هم شخصی رشد کنند و برای چالش‌های آینده آماده شوند.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(20, 20, 'fa', 'تمرکز اصلی: پایداری و برتری', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(21, 21, 'fa', 'ما بر پایداری و پیشرفت به موقع برای موفقیت دانش‌آموزان تمرکز داریم.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(22, 22, 'fa', 'دبیرستان', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(23, 23, 'fa', 'معلمان باتجربه، امکانات تخصصی و برنامه‌های پیشرفته', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(24, 24, 'fa', 'دبیرستان (پایه‌های 10 تا 12) در مدرسه سلمان فارسی توسط تیمی از معلمان باتجربه و استادان دانشگاه در رشته‌های علوم، علوم انسانی، ریاضیات، فیزیک و توسعه وب اداره می‌شود.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(25, 25, 'fa', 'آموزش پیشرفته علوم', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(26, 26, 'fa', 'استادان با تخصص در ریاضیات، زیست‌شناسی، شیمی و فیزیک، راهنمایی‌های عمیق و کارآمدی برای موفقیت تحصیلی ارائه می‌دهند.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(27, 27, 'fa', 'تصویر بخش احسان', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(28, 28, 'fa', 'تصویر بخش ابتدایی', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(29, 29, 'fa', 'تصویر بخش راهنمایی', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(30, 30, 'fa', 'تصویر بخش دبیرستان', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(31, 1, 'en', 'Educational Levels at Salman Farsi Complex', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(32, 2, 'en', 'Comprehensive and advanced educational program focused on nurturing talents and preparing students for a bright future', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(33, 3, 'en', 'EHSAN SECTION', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(34, 4, 'en', 'For Students with Special Needs', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(35, 5, 'en', 'Ehsan – Where Every Ability Finds Its Path', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(36, 6, 'en', 'Since 2008, Ehsan at the Salman Farsi Educational Complex has been a welcoming space for Students of Determination. Through expert support and a nurturing approach, we empower every student to unlock their potential and shape a brighter future.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(37, 7, 'en', 'Expert Teachers', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(38, 8, 'en', 'A team of specialists providing high-quality education and rehabilitation.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(39, 9, 'en', 'Comprehensive Support', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(40, 10, 'en', 'Ensuring equal opportunities for every student to succeed.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(41, 11, 'en', 'Read More', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(42, 12, 'en', 'ELEMENTARY SECTION', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(43, 13, 'en', 'From Foundational Excellence To Future Success', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(44, 14, 'en', 'Expert Guidance and Advanced Facilities', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(45, 15, 'en', 'The primary education section (Grades 1 to 6) offers two classes per grade, focusing on strong academics and advanced language programs in Arabic and English taught by native-speaking experts. With experienced teachers, innovative methods, and smart classrooms, we ensure an engaging and personalized learning experience.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(46, 16, 'en', 'MIDDLE SCHOOL', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(47, 17, 'en', 'Talented Educators, Modern Facilities, And Advanced Methods', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(48, 18, 'en', 'Middle school (grades 7 to 9) at Salman Farsi School offers a modern learning environment with smart classrooms and expert teachers. Each grade has two classes, supported by advanced teaching methods.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(49, 19, 'en', 'The school provides extracurricular programs, science labs, sports facilities, and amenities, ensuring students grow academically and personally while preparing for future challenges.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(50, 20, 'en', 'Key Focus: Consistency and Excellence', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(51, 21, 'en', 'We focus on consistency and timely progress for student success.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(52, 22, 'en', 'HIGH SCHOOL', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(53, 23, 'en', 'Experienced Educators, Specialized Facilities, And Cutting-Edge Programs', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(54, 24, 'en', 'High school (grades 10 to 12) at Salman Farsi School is guided by a team of experienced educators, many of whom are university professors specializing in science, humanities, mathematics, physics, and web development.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(55, 25, 'en', 'Advanced Science Instruction', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(56, 26, 'en', 'Professors provide expert guidance in biology, chemistry, and physics for academic success.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(57, 27, 'en', 'Ehsan section image', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(58, 28, 'en', 'Elementary section image', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(59, 29, 'en', 'Middle school section image', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(60, 30, 'en', 'High school section image', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(61, 1, 'ar', 'المستويات التعليمية في مجمع سلمان الفارسي', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(62, 2, 'ar', 'منهج شامل ومتقدم يركز على تنمية المواهب وإعداد الطلاب لمستقبل مشرق', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(63, 3, 'ar', 'قسم إحسان', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(64, 4, 'ar', 'للطلاب ذوي الاحتياجات الخاصة', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(65, 5, 'ar', 'إحسان - حيث تجد كل قدرة مسارها', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(66, 6, 'ar', 'منذ عام 2008 ، كان إحسان في مجمع سلمان الفارسي التعليمي مساحة ترحيبية للطلاب ذوي العزيمة. من خلال الدعم الخبير والنهج الراعي ، نمكن كل طالب من إطلاق إمكاناته وتشكيل مستقبل أكثر إشراقًا.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(67, 7, 'ar', 'معلمون خبراء', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(68, 8, 'ar', 'فريق من المتخصصين يقدمون تعليمًا وإعادة تأهيل عالية الجودة.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(69, 9, 'ar', 'دعم شامل', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(70, 10, 'ar', 'ضمان تكافؤ الفرص لكل طالب للنجاح.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(71, 11, 'ar', 'اقرأ أكثر', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(72, 12, 'ar', 'القسم الابتدائي', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(73, 13, 'ar', 'من التفوق التأسيسي إلى النجاح المستقبلي', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(74, 14, 'ar', 'التوجيه الخبير والمرافق المتقدمة', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(75, 15, 'ar', 'يقدم قسم التعليم الابتدائي (الصفوف من 1 إلى 6) فصلين دراسيين لكل صف، مع التركيز على الأكاديميين الأقوياء وبرامج اللغة المتقدمة في اللغتين العربية والإنجليزية التي يدرسها خبراء ناطقون باللغة الأم. مع المعلمين ذوي الخبرة والأساليب المبتكرة والفصول الدراسية الذكية، نضمن تجربة تعليمية جذابة ومخصصة.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(76, 16, 'ar', 'المدرسة المتوسطة', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(77, 17, 'ar', 'المعلمين الموهوبين والمرافق الحديثة والأساليب المتقدمة', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(78, 18, 'ar', 'توفر المدرسة المتوسطة (الصفوف من 7 إلى 9) في مدرسة سلمان الفارسي بيئة تعليمية حديثة مع فصول دراسية ذكية ومعلمين خبراء. كل صف يحتوي على فصلين دراسيين، مدعومين بأساليب تدريس متقدمة.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(79, 19, 'ar', 'توفر المدرسة برامج خارج المنهج ومختبرات علمية ومرافق رياضية ووسائل راحة، مما يضمن نمو الطلاب أكاديميًا وشخصيًا أثناء الاستعداد للتحديات المستقبلية.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(80, 20, 'ar', 'التركيز الرئيسي: الاتساق والتميز', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(81, 21, 'ar', 'نحن نركز على الاتساق والتقدم في الوقت المناسب لنجاح الطالب.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(82, 22, 'ar', 'المدرسة الثانوية', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(83, 23, 'ar', 'المعلمين ذوي الخبرة والمرافق المتخصصة والبرامج المتطورة', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(84, 24, 'ar', 'تدار المدرسة الثانوية (الصفوف من 10 إلى 12) في مدرسة سلمان الفارسي من قبل فريق من المعلمين ذوي الخبرة، وكثير منهم أساتذة جامعيون متخصصون في العلوم والإنسانيات والرياضيات والفيزياء وتطوير الويب.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(85, 25, 'ar', 'تعليم العلوم المتقدمة', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(86, 26, 'ar', 'يقدم الأساتذة توجيهات خبيرة في مجال الأحياء والكيمياء والفيزياء للنجاح الأكاديمي.', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(87, 27, 'ar', 'صورة قسم إحسان', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(88, 28, 'ar', 'صورة القسم الابتدائي', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(89, 29, 'ar', 'صورة قسم المدرسة المتوسطة', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(90, 30, 'ar', 'صورة قسم المدرسة الثانوية', '2025-05-13 09:23:09', '2025-05-13 09:23:09'),
(91, 102, 'fa', 'آزمایشگاه‌های پیشرفته علوم', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(92, 103, 'fa', 'برتری در توسعه وب', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(93, 104, 'fa', 'برنامه‌های فوق‌برنامه تخصصی', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(94, 106, 'fa', 'آزمایشگاه‌های کاملاً مجهز فرصتی برای انجام آزمایش‌های علمی در رشته‌های مختلف فراهم می‌آورند.', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(95, 107, 'fa', 'دانش‌آموزان از طریق کارگاه‌های مدرن کامپیوتری، تجربه عملی در زمینه توسعه وب کسب می‌کنند.', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(96, 108, 'fa', 'برنامه‌های متنوع فوق‌برنامه، دانش‌آموزان را در زمینه‌های علوم انسانی، ریاضی و فناوری تقویت می‌کند.', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(97, 102, 'en', 'State-of-the-Art Science Labs', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(98, 103, 'en', 'Web Development Excellence', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(99, 104, 'en', 'Tailored Extracurricular Programs', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(100, 106, 'en', 'Fully equipped labs enable practical experiments in core sciences.', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(101, 107, 'en', 'Students gain hands-on experience in modern computer labs tailored for web development.', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(102, 108, 'en', 'Diverse activities support students in humanities, mathematics, and technology.', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(103, 102, 'ar', 'مختبرات علوم متطورة', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(104, 103, 'ar', 'التميز في تطوير الويب', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(105, 104, 'ar', 'برامج خارج المنهج مخصصة', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(106, 106, 'ar', 'تتيح المختبرات المجهزة بالكامل إجراء تجارب عملية في العلوم الأساسية.', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(107, 107, 'ar', 'يكتسب الطلاب خبرة عملية في مختبرات الكمبيوتر الحديثة المصممة خصيصًا لتطوير الويب.', '2025-05-13 11:39:15', '2025-05-13 11:39:15'),
(108, 108, 'ar', 'تدعم الأنشطة المتنوعة الطلاب في مجالات العلوم الإنسانية والرياضيات والتكنولوجيا.', '2025-05-13 11:39:15', '2025-05-13 11:39:15');
