INSERT INTO `temp_ehsan_translations` (`translation_id`, `content_id`, `language_id`, `content_value`, `created_at`, `updated_at`) VALUES
(1, 1, 'fa', 'بخش احسان - دانش‌آموزان با نیازهای ویژه', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(2, 2, 'fa', 'حمایت، توانمندسازی و پرورش استعدادهای ویژه', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(3, 3, 'fa', 'معرفی بخش احسان', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(4, 4, 'fa', 'مجتمع آموزشی سلمان فارسی با تعهدی راسخ، برای حمایت از دانش‌آموزان با نیازهای ویژه (Students of Determination) در مسیر رشد و پیشرفتشان فعالیت می‌کند. این مجموعه در سال 1995 فعالیت خود را آغاز کرد و طی سال‌ها پذیرای صدها دانش‌آموز بوده است. در سال 2008، اولین بخش تخصصی خود با نام «احسان» را به‌منظور ارائه خدمات آموزشی و توان‌بخشی به این دانش‌آموزان افتتاح کرد.', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(5, 5, 'fa', 'هدف اصلی بخش احسان، شناسایی ظرفیت‌ها و توانمندی‌های همه دانش‌آموزان و فراهم‌کردن فرصت‌هایی برای رشد، یادگیری و مشارکت آن‌ها در فعالیت‌های متنوع آموزشی و غنی‌سازی است. ما به برابری و ایجاد فرصت‌های برابر برای همه اعتقاد داریم و تلاش می‌کنیم زمینه‌ای را فراهم آوریم تا دانش‌آموزان بتوانند آینده‌ای روشن برای خود بسازند.', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(6, 6, 'fa', 'اهداف بخش احسان', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(7, 7, 'fa', '{\"title\":\"ارائه تجارب آموزشی برای رشد توانایی‌ها\",\"description\":\"ارائه تجارب آموزشی که دانش‌آموزان را قادر سازد به تمام توانایی‌های خود دست یابند.\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(8, 8, 'fa', '{\"title\":\"ایجاد محیط مثبت برای تقویت اعتماد‌به‌نفس\",\"description\":\"ایجاد محیطی مثبت که در آن دانش‌آموزان اعتمادبه‌نفس و عزت‌نفس خود را تقویت کنند.\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(9, 9, 'fa', '{\"title\":\"ارزش‌گذاری به نیازها و دیدگاه‌ها\",\"description\":\"ارزش‌گذاری به نیازها و دیدگاه‌های دانش‌آموزان با نیازهای ویژه و پاسخ‌گویی به خواسته‌های آن‌ها.\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(10, 10, 'fa', '{\"title\":\"فراهم‌کردن بستر ورود به جامعه\",\"description\":\"فراهم‌کردن بستری برای ورود دانش‌آموزان دارای نیازهای ویژه به جامعه با ارزش‌های اخلاقی و مهارت‌های شغلی مناسب.\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(11, 11, 'fa', '{\"title\":\"تربیت دانش‌آموزان موفق در همه زمینه‌ها\",\"description\":\"تربیت دانش‌آموزانی که نه‌تنها در حوزه‌های علمی بلکه در ارزش‌های اخلاقی، اجتماعی و شهروندی موفق باشند.\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(12, 12, 'fa', 'گفتاردرمانی ؛ یکی از خدمات توان‌بخشی بخش احسان', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(13, 13, 'fa', 'واحد گفتاردرمانی بخش احسان به ارزیابی و درمان اختلالات گفتار و زبان دانش‌آموزان می‌پردازد. این خدمات نقش کلیدی در بهبود توانایی‌های ارتباطی دانش‌آموزان دارد، زیرا گفتار و زبان از مهم‌ترین ابزارهای برقراری ارتباط هستند.', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(14, 14, 'fa', 'حیطه‌های خدمات گفتاردرمانی', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(15, 15, 'fa', '', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(16, 16, 'fa', '', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(17, 17, 'fa', '{\"title\":\"تأخیر در رشد گفتار و زبان\",\"description\":\"شامل کودکانی که محیط مناسبی برای رشد گفتار و زبان نداشته یا دچار ناتوانی ذهنی هستند.\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(18, 18, 'fa', '{\"title\":\"مشکلات یادگیری\",\"description\":\"شامل اختلالات در خواندن و نوشتن.\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(19, 19, 'fa', '{\"title\":\"اختلال تولید\",\"description\":\"ناشی از عدم هماهنگی عضلات زبان، کم‌شنوایی یا ضعف حسی دهان.\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(20, 20, 'fa', '{\"title\":\"لکنت\",\"description\":\"گفتاری که همراه با تکرار، کشش، مکث یا گیر است و گاهی ناشی از فقر واژگان یا اختلالات عصبی است.\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(21, 21, 'fa', 'خدمات ارائه‌شده در واحد گفتاردرمانی', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(22, 22, 'fa', '{\"title\":\"ارزیابی اولیه و تعیین سطح\",\"description\":\"ارزیابی اولیه و تعیین سطح اختلال گفتار و زبان.\",\"icon\":\"fas fa-clipboard-check\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(23, 23, 'fa', '{\"title\":\"برنامه‌ریزی و اجرای دقیق درمان\",\"description\":\"برنامه‌ریزی و اجرای دقیق درمان.\",\"icon\":\"fas fa-tasks\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(24, 24, 'fa', '{\"title\":\"مشاوره و راهنمایی خانواده‌ها\",\"description\":\"مشاوره و راهنمایی خانواده‌ها.\",\"icon\":\"fas fa-users\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(25, 25, 'fa', '{\"title\":\"تقویت سیستم حسی-عصبی\",\"description\":\"تقویت سیستم حسی-عصبی و مهارت‌های پایه گفتاری مانند جویدن و بلع.\",\"icon\":\"fas fa-brain\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(26, 26, 'fa', '{\"title\":\"ارتقای مهارت‌های ارتباطی\",\"description\":\"ارتقای مهارت‌های ارتباطی دانش‌آموز با استفاده از روش‌های رفتاری، شناختی و زبانی.\",\"icon\":\"fas fa-comments\"}', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(27, 27, 'fa', 'مسیر موفقیت و توانمندی', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(28, 28, 'fa', 'بخش احسان، با ترکیبی از تعهد و تخصص، به دانش‌آموزان با نیازهای ویژه کمک می‌کند تا مسیر موفقیت و توانمندی را با اطمینان طی کنند. ما با رویکردی مبتنی بر احترام و توجه به تفاوت‌های فردی، شرایطی را فراهم می‌آوریم که هر دانش‌آموز بتواند استعدادهای خود را به بهترین شکل شکوفا سازد.', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(29, 29, 'fa', 'برای اطلاعات بیشتر با ما تماس بگیرید', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(30, 30, 'fa', 'خانواده‌های محترم، برای کسب اطلاعات بیشتر درباره خدمات بخش احسان و شرایط ثبت‌نام، با ما در تماس باشید.', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(31, 31, 'fa', 'تماس با ما', '2025-05-13 08:06:07', '2025-05-13 08:06:07'),
(32, 1, 'en', 'Ehsan Department - Students of Determination', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(33, 2, 'en', 'Supporting, Empowering, and Nurturing Special Talents', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(34, 3, 'en', 'Introduction to Ehsan', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(35, 4, 'en', 'The Salman Farsi Educational Complex is committed to supporting Students of Determination (SOD) in their journey toward growth and development. Established in 1995, the complex has welcomed hundreds of students over the years. In 2008, it launched its first specialized department, named Ehsan, to provide educational and rehabilitation services to students with special needs.', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(36, 5, 'en', 'The primary goal of Ehsan is to recognize the potential and capabilities of all students while creating opportunities for their enrichment and learning. We believe in equality and equal opportunities for everyone, striving to provide a supportive environment where students can shape a brighter future for themselves.', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(37, 6, 'en', 'Objectives of Ehsan', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(38, 7, 'en', '{\"title\":\"Provide Learning Experiences for Full Potential\",\"description\":\"To offer learning experiences that enable students to achieve their full potential.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(39, 8, 'en', '{\"title\":\"Create a Positive Environment for Confidence\",\"description\":\"To create a positive environment where students can build self-confidence and self-respect.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(40, 9, 'en', '{\"title\":\"Value Needs and Perspectives\",\"description\":\"To value the needs and perspectives of Students of Determination and address their aspirations.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(41, 10, 'en', '{\"title\":\"Prepare for Social Integration\",\"description\":\"To ensure that students with special needs can integrate into society with appropriate ethical values and vocational skills.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(42, 11, 'en', '{\"title\":\"Develop Well-Rounded Students\",\"description\":\"To develop students—not just those with special needs but all students—into responsible citizens equipped with proper social etiquette, ethics, and values to contribute to their future.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(43, 12, 'en', 'Speech Therapy -- A Key Rehabilitation Service', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(44, 13, 'en', 'The speech therapy unit within Ehsan focuses on assessing and treating speech and language disorders in students. This service plays a crucial role in enhancing students\' communication skills, as speech and language are vital tools for interaction.', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(45, 14, 'en', 'Areas of Speech Therapy Services', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(46, 15, 'en', '', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(47, 16, 'en', '', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(48, 17, 'en', '{\"title\":\"Delayed Speech and Language Development\",\"description\":\"For children who lack an environment conducive to speech and language development or have intellectual disabilities.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(49, 18, 'en', '{\"title\":\"Learning Disorders\",\"description\":\"Including challenges related to reading and writing.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(50, 19, 'en', '{\"title\":\"Articulation Disorders\",\"description\":\"Arising from coordination issues in tongue muscles, hearing impairments, or sensory weaknesses in the oral region.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(51, 20, 'en', '{\"title\":\"Stuttering\",\"description\":\"Speech characterized by repetition, prolongation, pauses, or blocks, sometimes caused by vocabulary deficiencies or neurological disorders.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(52, 21, 'en', 'Services Provided by the Speech Therapy Unit', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(53, 22, 'en', '{\"title\":\"Initial Evaluation\",\"description\":\"Initial evaluation and determination of the severity of speech and language disorders.\",\"icon\":\"fas fa-clipboard-check\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(54, 23, 'en', '{\"title\":\"Treatment Planning\",\"description\":\"Planning and precise implementation of treatment programs.\",\"icon\":\"fas fa-tasks\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(55, 24, 'en', '{\"title\":\"Family Counseling\",\"description\":\"Counseling and guiding families.\",\"icon\":\"fas fa-users\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(56, 25, 'en', '{\"title\":\"Sensory-Motor Enhancement\",\"description\":\"Enhancing sensory-motor systems and foundational speech skills, including chewing and swallowing.\",\"icon\":\"fas fa-brain\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(57, 26, 'en', '{\"title\":\"Communication Skills Improvement\",\"description\":\"Improving students\' communication skills using behavioral, cognitive, and linguistic approaches.\",\"icon\":\"fas fa-comments\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(58, 27, 'en', 'A Path to Success and Empowerment', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(59, 28, 'en', 'With a combination of dedication and expertise, the Ehsan department supports students with special needs, helping them confidently navigate their path to success and empowerment. Through an approach based on respect and attention to individual differences, we create conditions where each student can develop their talents in the best possible way.', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(60, 29, 'en', 'Contact Us for More Information', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(61, 30, 'en', 'Respected families, for more information about Ehsan department services and registration conditions, please contact us.', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(62, 31, 'en', 'Contact Us', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(63, 1, 'ar', 'قسم إحسان - طلاب أصحاب الهمم', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(64, 2, 'ar', 'دعم وتمكين ورعاية المواهب الخاصة', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(65, 3, 'ar', 'مقدمة عن إحسان', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(66, 4, 'ar', 'يلتزم مجمع سلمان الفارسي التعليمي بدعم الطلاب أصحاب الهمم في رحلتهم نحو النمو والتطور. تأسس المجمع عام 1995، واستقبل مئات الطلاب على مر السنين. في عام 2008، أطلق أول قسم متخصص، باسم إحسان، لتقديم الخدمات التعليمية والتأهيلية للطلاب ذوي الاحتياجات الخاصة.', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(67, 5, 'ar', 'الهدف الأساسي لإحسان هو التعرف على إمكانات وقدرات جميع الطلاب مع خلق فرص لإثرائهم وتعلمهم. نحن نؤمن بالمساواة وتكافؤ الفرص للجميع، ونسعى جاهدين لتوفير بيئة داعمة حيث يمكن للطلاب تشكيل مستقبل أكثر إشراقًا لأنفسهم.', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(68, 6, 'ar', 'أهداف إحسان', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(69, 7, 'ar', '{\"title\":\"توفير تجارب تعليمية لكامل الإمكانات\",\"description\":\"لتقديم تجارب تعليمية تمكن الطلاب من تحقيق كامل إمكاناتهم.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(70, 8, 'ar', '{\"title\":\"خلق بيئة إيجابية للثقة\",\"description\":\"لخلق بيئة إيجابية حيث يمكن للطلاب بناء الثقة بالنفس واحترام الذات.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(71, 9, 'ar', '{\"title\":\"تقدير الاحتياجات والآراء\",\"description\":\"لتقدير احتياجات وآراء الطلاب أصحاب الهمم وتلبية تطلعاتهم.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(72, 10, 'ar', '{\"title\":\"التحضير للاندماج الاجتماعي\",\"description\":\"لضمان أن الطلاب ذوي الاحتياجات الخاصة يمكنهم الاندماج في المجتمع بقيم أخلاقية ومهارات مهنية مناسبة.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(73, 11, 'ar', '{\"title\":\"تطوير طلاب متكاملين\",\"description\":\"لتطوير الطلاب - ليس فقط أولئك ذوي الاحتياجات الخاصة ولكن جميع الطلاب - ليصبحوا مواطنين مسؤولين مجهزين بآداب اجتماعية وأخلاق وقيم مناسبة للمساهمة في مستقبلهم.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(74, 12, 'ar', 'علاج النطق -- خدمة تأهيل رئيسية', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(75, 13, 'ar', 'تركز وحدة علاج النطق داخل إحسان على تقييم وعلاج اضطرابات النطق واللغة لدى الطلاب. تلعب هذه الخدمة دورًا حاسمًا في تعزيز مهارات التواصل لدى الطلاب، حيث أن النطق واللغة أدوات حيوية للتفاعل.', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(76, 14, 'ar', 'مجالات خدمات علاج النطق', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(77, 15, 'ar', '', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(78, 16, 'ar', '', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(79, 17, 'ar', '{\"title\":\"تأخر النطق وتطور اللغة\",\"description\":\"للأطفال الذين يفتقرون إلى بيئة مواتية لتطور النطق واللغة أو لديهم إعاقات ذهنية.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(80, 18, 'ar', '{\"title\":\"اضطرابات التعلم\",\"description\":\"بما في ذلك التحديات المتعلقة بالقراءة والكتابة.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(81, 19, 'ar', '{\"title\":\"اضطرابات النطق\",\"description\":\"الناشئة عن مشاكل في تناسق عضلات اللسان، أو ضعف السمع، أو الضعف الحسي في منطقة الفم.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(82, 20, 'ar', '{\"title\":\"التأتأة\",\"description\":\"كلام يتميز بالتكرار، الإطالة، التوقفات، أو التوقف المفاجئ، وأحيانًا يكون سببه نقص في المفردات أو اضطرابات عصبية.\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(83, 21, 'ar', 'الخدمات التي تقدمها وحدة علاج النطق', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(84, 22, 'ar', '{\"title\":\"التقييم الأولي\",\"description\":\"التقييم الأولي وتحديد شدة اضطرابات النطق واللغة.\",\"icon\":\"fas fa-clipboard-check\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(85, 23, 'ar', '{\"title\":\"تخطيط العلاج\",\"description\":\"التخطيط والتنفيذ الدقيق لبرامج العلاج.\",\"icon\":\"fas fa-tasks\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(86, 24, 'ar', '{\"title\":\"استشارة الأسرة\",\"description\":\"تقديم المشورة وتوجيه الأسر.\",\"icon\":\"fas fa-users\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(87, 25, 'ar', '{\"title\":\"تعزيز الجهاز الحسي الحركي\",\"description\":\"تعزيز الأنظمة الحسية الحركية ومهارات النطق الأساسية، بما في ذلك المضغ والبلع.\",\"icon\":\"fas fa-brain\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(88, 26, 'ar', '{\"title\":\"تحسين مهارات التواصل\",\"description\":\"تحسين مهارات التواصل لدى الطلاب باستخدام أساليب سلوكية ومعرفية ولغوية.\",\"icon\":\"fas fa-comments\"}', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(89, 27, 'ar', 'طريق النجاح والتمكين', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(90, 28, 'ar', 'من خلال مزيج من التفاني والخبرة، يدعم قسم إحسان الطلاب ذوي الاحتياجات الخاصة، ويساعدهم في الانتقال بثقة في طريقهم نحو النجاح والتمكين. من خلال نهج قائم على الاحترام والاهتمام بالاختلافات الفردية، نخلق ظروفًا يمكن لكل طالب من خلالها تطوير مواهبه بأفضل طريقة ممكنة.', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(91, 29, 'ar', 'اتصل بنا لمزيد من المعلومات', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(92, 30, 'ar', 'الأسر المحترمة، لمزيد من المعلومات حول خدمات قسم إحسان وشروط التسجيل، يرجى الاتصال بنا.', '2025-05-13 08:06:08', '2025-05-13 08:06:08'),
(93, 31, 'ar', 'اتصل بنا', '2025-05-13 08:06:08', '2025-05-13 08:06:08');
