INSERT INTO `temp_facilities_translations` (`translation_id`, `content_id`, `language_id`, `content_value`, `created_at`, `updated_at`) VALUES
(1, 1, 'fa', 'امکانات و خدمات', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(2, 2, 'fa', 'محیطی پویا برای رشد و یادگیری', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(3, 3, 'fa', 'محیطی پویا برای رشد و یادگیری', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(4, 4, 'fa', 'مجتمع آموزشی سلمان فارسی', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(5, 5, 'fa', 'مجتمع آموزشی سلمان فارسی محیطی پویا را برای رشد جامع دانش‌آموزان در زمینه‌های علمی، ورزشی، فرهنگی و اجتماعی فراهم کرده است. با زیرساخت‌های مدرن و امکانات پیشرفته، این مجموعه به پرورش افرادی خلاق، متعهد و توانمند برای موفقیت در جنبه‌های مختلف زندگی اختصاص یافته است.', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(6, 6, 'fa', '{\"title\":\"کلاس‌های هوشمند و ابزارهای آموزشی مدرن\",\"subtitle\":\"امکانات و خدمات\",\"description\":\"هر کلاس درس مجهز به تخته‌های هوشمند، پروژکتورهای پیشرفته و سیستم‌های صوتی-تصویری است که امکان یادگیری تعاملی و جذاب را فراهم می‌کند. با ادغام فناوری‌های پیشرفته آموزشی، مجتمع کیفیت یادگیری را ارتقا داده و دانش‌آموزان را به طور فعال در فرآیند آموزشی درگیر می‌کند.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(7, 7, 'fa', '{\"title\":\"آزمایشگاه‌های علمی پیشرفته\",\"subtitle\":\"امکانات و خدمات\",\"description\":\"مجتمع دارای آزمایشگاه‌های کاملا مجهز شیمی و زیست‌شناسی است که محیطی عملی و محرک برای انجام آزمایش‌ها، پروژه‌های تحقیقاتی و ارتقای مهارت‌ها در علوم را فراهم می‌کند.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(8, 8, 'fa', '{\"title\":\"کتابخانه جامع\",\"subtitle\":\"امکانات و خدمات\",\"description\":\"با هزاران کتاب چاپی، کتابخانه فضایی آرام و پر منبع برای مطالعه و تحقیق فراهم می‌کند. ابزارهای جستجوی دیجیتال و دسترسی به منابع علمی، دانش‌آموزان را در دستیابی به برتری تحصیلی و پژوهشی پشتیبانی می‌کند.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(9, 9, 'fa', '{\"title\":\"امکانات ورزشی و فضاهای تفریحی\",\"subtitle\":\"امکانات و خدمات\",\"description\":\"مجتمع آموزشی سلمان فارسی دارای امکانات ورزشی متنوع برای تقویت سلامت جسمی و روحیه کار تیمی دانش‌آموزان است.\",\"features\":[\"چندین زمین چمن ورزشی\",\"سالن‌های ورزشی چندمنظوره داخلی\",\"امکانات برای فعالیت‌هایی مانند فوتبال، والیبال، بسکتبال و تنیس روی میز\"],\"additional_text\":\"این امکانات، همراه با برنامه‌های ورزشی سازمان‌یافته، سلامت جسمی و کار تیمی را تشویق می‌کنند.\"}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(10, 10, 'fa', '{\"title\":\"فعالیت‌های فرهنگی و هنری\",\"subtitle\":\"امکانات و خدمات\",\"description\":\"مجتمع سلمان فارسی با ارائه برنامه‌های غنی فرهنگی و هنری، به پرورش استعدادهای چندبعدی دانش‌آموزان کمک می‌کند.\",\"features\":[\"جشن‌های ملی و مذهبی\",\"نمایشگاه‌های هنری و کارگاه‌های خلاقیت\",\"آموزش هنرهایی مانند نقاشی، موسیقی و تئاتر\"]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(11, 11, 'fa', '{\"title\":\"نمازخانه و برنامه‌های مذهبی\",\"subtitle\":\"امکانات و خدمات\",\"description\":\"نمازخانه محیطی دلنشین برای نمازهای جماعت، جلسات قرآنی و بحث‌های اخلاقی فراهم می‌کند که به رشد معنوی و اخلاقی دانش‌آموزان کمک می‌کند.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(12, 12, 'fa', '{\"title\":\"درمانگاه سلامت و خدمات تندرستی\",\"subtitle\":\"امکانات و خدمات\",\"description\":\"درمانگاه سلامت، تحت نظارت متخصصان پزشکی واجد شرایط، خدمات زیر را ارائه می‌دهد:\",\"features\":[\"معاینات پزشکی معمول\",\"برنامه‌های واکسیناسیون\",\"مشاوره تغذیه و روانشناسی\"],\"additional_text\":\"این خدمات با هدف حفظ و بهبود سلامت جسمی و روانی دانش‌آموزان ارائه می‌شود.\"}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(13, 13, 'fa', '{\"title\":\"خدمات مشاوره و راهنمایی\",\"subtitle\":\"امکانات و خدمات\",\"description\":\"مشاوران حرفه‌ای به دانش‌آموزان در زمینه‌های تحصیلی، عاطفی و اجتماعی از طریق موارد زیر کمک می‌کنند:\",\"features\":[\"مشاوره فردی و گروهی\",\"کارگاه‌های مهارت‌های زندگی\",\"جلسات راهنمایی شغلی\"]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(14, 14, 'fa', '{\"title\":\"سالن غذاخوری بهداشتی با غذاهای مغذی\",\"subtitle\":\"امکانات و خدمات\",\"description\":\"سالن غذاخوری دسترسی به وعده‌های غذایی و میان‌وعده‌های سالم و مغذی را تضمین می‌کند و رژیم‌های غذایی متعادل را برای حفظ انرژی و سلامت کلی دانش‌آموزان ترویج می‌دهد.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(15, 15, 'fa', '{\"title\":\"پشتیبانی از دانش‌آموزان با نیازهای ویژه\",\"subtitle\":\"امکانات و خدمات\",\"description\":\"خدمات تخصصی برای دانش‌آموزان با نیازهای ویژه، شامل موارد زیر است:\",\"features\":[\"گفتاردرمانی و توانبخشی\",\"مشاوره شخصی‌سازی شده\",\"برنامه‌های توسعه مهارت‌های اجتماعی\"]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(16, 16, 'fa', '{\"title\":\"ایمنی و آمادگی بحران\",\"subtitle\":\"امکانات و خدمات\",\"description\":\"مجتمع از پروتکل‌های ایمنی سختگیرانه‌ای پیروی می‌کند و دوره‌هایی درباره مدیریت بحران، ایمنی آتش‌سوزی و آمادگی زلزله ارائه می‌دهد تا دانش‌آموزان را برای شرایط اضطراری آماده کند.\",\"features\":[],\"focus_title\":\"تمرکز ویژه: آموزش مدیریت بحران\",\"focus_text\":\"ما دانش‌آموزان را با دانش و مهارت‌های لازم برای مدیریت مؤثر شرایط اضطراری توانمند می‌کنیم و آنها را برای هر موقعیت غیرمنتظره آماده می‌کنیم.\"}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(17, 1, 'en', 'Facilities & Services', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(18, 2, 'en', 'A Thriving Environment for Growth and Learning', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(19, 3, 'en', 'A Thriving Environment for Growth and Learning', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(20, 4, 'en', 'Salman Farsi Educational Complex', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(21, 5, 'en', 'The Salman Farsi Educational Complex offers a dynamic setting designed to foster comprehensive student development in academic, athletic, cultural, and social spheres. Equipped with modern infrastructure and state-of-the-art facilities, the complex is dedicated to nurturing creative, committed, and capable individuals prepared to excel in various aspects of life.', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(22, 6, 'en', '{\"title\":\"Smart Classrooms and Modern Educational Tools\",\"subtitle\":\"Facilities and Services\",\"description\":\"Each classroom is outfitted with smart boards, advanced projectors, and audio-visual systems, enabling interactive and engaging learning experiences. By integrating cutting-edge educational technologies, the complex enhances learning quality and actively involves students in the educational process.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(23, 7, 'en', '{\"title\":\"Advanced Scientific Laboratories\",\"subtitle\":\"Facilities and Services\",\"description\":\"The complex features fully equipped laboratories for chemistry and biology, providing a practical and stimulating environment for experiments, research projects, and skill enhancement in the sciences.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(24, 8, 'en', '{\"title\":\"Comprehensive Library\",\"subtitle\":\"Facilities and Services\",\"description\":\"With thousands of printed books, the library offers a quiet, resourceful space for study and research. Digital search tools and access to scientific resources further support students in achieving academic and research excellence.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(25, 9, 'en', '{\"title\":\"Sports Facilities and Recreation Areas\",\"subtitle\":\"Facilities and Services\",\"description\":\"The Salman Farsi Educational Complex offers diverse sports facilities to enhance students\' physical health and teamwork spirit.\",\"features\":[\"Multiple grass sports fields\",\"Multifunctional indoor sports halls\",\"Facilities for activities such as football, volleyball, basketball, and table tennis\"],\"additional_text\":\"These amenities, coupled with organized sports programs, encourage physical health and teamwork.\"}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(26, 10, 'en', '{\"title\":\"Cultural and Artistic Activities\",\"subtitle\":\"Facilities and Services\",\"description\":\"The Salman Farsi Complex helps develop students\' multidimensional talents through rich cultural and artistic programs.\",\"features\":[\"National and religious celebrations\",\"Art exhibitions and creativity workshops\",\"Training in arts such as painting, music, and theater\"]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(27, 11, 'en', '{\"title\":\"Prayer Hall and Religious Programs\",\"subtitle\":\"Facilities and Services\",\"description\":\"The prayer hall provides a welcoming environment for congregational prayers, Quranic sessions, and ethical discussions, fostering students\' spiritual and moral growth.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(28, 12, 'en', '{\"title\":\"Health Clinic and Wellness Services\",\"subtitle\":\"Facilities and Services\",\"description\":\"Supervised by qualified medical professionals, the health clinic offers:\",\"features\":[\"Routine medical check-ups\",\"Vaccination programs\",\"Nutritional and psychological counseling\"],\"additional_text\":\"These services aim to maintain and improve the physical and mental health of students.\"}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(29, 13, 'en', '{\"title\":\"Counseling and Guidance Services\",\"subtitle\":\"Facilities and Services\",\"description\":\"Professional counselors support students academically, emotionally, and socially through:\",\"features\":[\"Individual and group counseling\",\"Life skills workshops\",\"Career guidance sessions\"]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(30, 14, 'en', '{\"title\":\"Hygienic Cafeteria with Nutritious Meals\",\"subtitle\":\"Facilities and Services\",\"description\":\"The cafeteria ensures access to healthy, nutritious meals and snacks, promoting balanced diets to sustain student energy and overall well-being.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(31, 15, 'en', '{\"title\":\"Support for Students with Special Needs\",\"subtitle\":\"Facilities and Services\",\"description\":\"Specialized services cater to students with unique needs, including:\",\"features\":[\"Speech therapy and rehabilitation\",\"Personalized counseling\",\"Social skills development programs\"]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(32, 16, 'en', '{\"title\":\"Safety and Crisis Preparedness\",\"subtitle\":\"Facilities and Services\",\"description\":\"The complex adheres to rigorous safety protocols, providing courses on crisis management, fire safety, and earthquake preparedness to equip students for emergencies.\",\"features\":[],\"focus_title\":\"Key Focus: Crisis Management Training\",\"focus_text\":\"We empower students with the knowledge and skills to handle emergencies effectively, preparing them for any unexpected situation.\"}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(33, 1, 'ar', 'المرافق والخدمات', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(34, 2, 'ar', 'بيئة مزدهرة للنمو والتعلم', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(35, 3, 'ar', 'بيئة مزدهرة للنمو والتعلم', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(36, 4, 'ar', 'مجمع سلمان الفارسي التعليمي', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(37, 5, 'ar', 'يقدم مجمع سلمان الفارسي التعليمي بيئة ديناميكية مصممة لتعزيز التطوير الشامل للطلاب في المجالات الأكاديمية والرياضية والثقافية والاجتماعية. مجهز ببنية تحتية حديثة ومرافق متطورة، المجمع مكرس لرعاية أفراد مبدعين وملتزمين وقادرين مستعدين للتفوق في مختلف جوانب الحياة.', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(38, 6, 'ar', '{\"title\":\"الفصول الدراسية الذكية وأدوات التعليم الحديثة\",\"subtitle\":\"المرافق والخدمات\",\"description\":\"تم تجهيز كل فصل دراسي بالسبورات الذكية وأجهزة العرض المتطورة وأنظمة الصوت والصورة، مما يتيح تجارب تعليمية تفاعلية وجذابة. من خلال دمج تقنيات التعليم المتطورة، يعزز المجمع جودة التعلم ويشرك الطلاب بنشاط في العملية التعليمية.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(39, 7, 'ar', '{\"title\":\"المختبرات العلمية المتقدمة\",\"subtitle\":\"المرافق والخدمات\",\"description\":\"يضم المجمع مختبرات مجهزة بالكامل للكيمياء والأحياء، مما يوفر بيئة عملية ومحفزة للتجارب ومشاريع البحث وتعزيز المهارات في العلوم.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(40, 8, 'ar', '{\"title\":\"مكتبة شاملة\",\"subtitle\":\"المرافق والخدمات\",\"description\":\"مع آلاف الكتب المطبوعة، توفر المكتبة مساحة هادئة وغنية بالموارد للدراسة والبحث. تدعم أدوات البحث الرقمية والوصول إلى الموارد العلمية الطلاب في تحقيق التفوق الأكاديمي والبحثي.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(41, 9, 'ar', '{\"title\":\"المرافق الرياضية ومناطق الترفيه\",\"subtitle\":\"المرافق والخدمات\",\"description\":\"يقدم مجمع سلمان الفارسي التعليمي مرافق رياضية متنوعة لتعزيز الصحة البدنية للطلاب وروح العمل الجماعي.\",\"features\":[\"ملاعب رياضية عشبية متعددة\",\"صالات رياضية داخلية متعددة الوظائف\",\"مرافق لأنشطة مثل كرة القدم والكرة الطائرة وكرة السلة وتنس الطاولة\"],\"additional_text\":\"هذه المرافق، إلى جانب البرامج الرياضية المنظمة، تشجع الصحة البدنية والعمل الجماعي.\"}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(42, 10, 'ar', '{\"title\":\"الأنشطة الثقافية والفنية\",\"subtitle\":\"المرافق والخدمات\",\"description\":\"يساعد مجمع سلمان الفارسي في تطوير مواهب الطلاب متعددة الأبعاد من خلال برامج ثقافية وفنية غنية.\",\"features\":[\"الاحتفالات الوطنية والدينية\",\"معارض الفن وورش الإبداع\",\"التدريب في الفنون مثل الرسم والموسيقى والمسرح\"]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(43, 11, 'ar', '{\"title\":\"قاعة الصلاة والبرامج الدينية\",\"subtitle\":\"المرافق والخدمات\",\"description\":\"توفر قاعة الصلاة بيئة مرحبة للصلوات الجماعية وجلسات القرآن والمناقشات الأخلاقية، مما يعزز النمو الروحي والأخلاقي للطلاب.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(44, 12, 'ar', '{\"title\":\"العيادة الصحية وخدمات العافية\",\"subtitle\":\"المرافق والخدمات\",\"description\":\"تحت إشراف متخصصين طبيين مؤهلين، تقدم العيادة الصحية:\",\"features\":[\"الفحوصات الطبية الروتينية\",\"برامج التطعيم\",\"الاستشارات الغذائية والنفسية\"],\"additional_text\":\"تهدف هذه الخدمات إلى الحفاظ على الصحة البدنية والعقلية للطلاب وتحسينها.\"}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(45, 13, 'ar', '{\"title\":\"خدمات الإرشاد والتوجيه\",\"subtitle\":\"المرافق والخدمات\",\"description\":\"يدعم المستشارون المحترفون الطلاب أكاديميًا وعاطفيًا واجتماعيًا من خلال:\",\"features\":[\"الاستشارات الفردية والجماعية\",\"ورش عمل مهارات الحياة\",\"جلسات التوجيه المهني\"]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(46, 14, 'ar', '{\"title\":\"كافتيريا صحية مع وجبات مغذية\",\"subtitle\":\"المرافق والخدمات\",\"description\":\"تضمن الكافتيريا الوصول إلى وجبات ووجبات خفيفة صحية ومغذية، وتعزز النظم الغذائية المتوازنة للحفاظ على طاقة الطلاب ورفاههم بشكل عام.\",\"features\":[]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(47, 15, 'ar', '{\"title\":\"دعم الطلاب ذوي الاحتياجات الخاصة\",\"subtitle\":\"المرافق والخدمات\",\"description\":\"تلبي الخدمات المتخصصة احتياجات الطلاب الفريدة، بما في ذلك:\",\"features\":[\"علاج النطق وإعادة التأهيل\",\"الاستشارات الشخصية\",\"برامج تنمية المهارات الاجتماعية\"]}', '2025-05-13 11:58:17', '2025-05-13 11:58:17'),
(48, 16, 'ar', '{\"title\":\"السلامة والتأهب للأزمات\",\"subtitle\":\"المرافق والخدمات\",\"description\":\"يلتزم المجمع ببروتوكولات سلامة صارمة، ويوفر دورات عن إدارة الأزمات والسلامة من الحرائق والتأهب للزلازل لتجهيز الطلاب للطوارئ.\",\"features\":[],\"focus_title\":\"التركيز الرئيسي: تدريب إدارة الأزمات\",\"focus_text\":\"نمكّن الطلاب بالمعرفة والمهارات للتعامل مع حالات الطوارئ بشكل فعال، ونعدهم لأي موقف غير متوقع.\"}', '2025-05-13 11:58:17', '2025-05-13 11:58:17');
