INSERT INTO `temp_page_translations` (`translation_id`, `page_id`, `language_id`, `title`, `meta_description`, `meta_keywords`, `slug`, `created_at`, `updated_at`) VALUES
(1, 1, 'fa', 'صفحه اصلی', 'مجتمع آموزشی سلمان فارسی - مجتمع آموزشی ایرانی در دبی', 'مجتمع آموزشی سلمان فارسی، مدرسه ایرانی دبی، آموزش به زبان فارسی در امارات، مدارس ایرانی دبی، تحصیل در دبی، آموزش با کیفیت ایرانی، سلمان فارسی دبی، مدرسه ایرانی امارات متحده عربی', 'home', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(2, 1, 'en', 'Home', 'Salman Farsi Educational Complex - Iranian School in Dubai', 'Salman Farsi Educational Complex, Iranian school Dubai, Persian education UAE, Iranian school Emirates, education in Dubai, quality Iranian education, Salman Farsi Dubai, Iranian school United Arab Emirates', 'home', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(3, 1, 'ar', 'الصفحة الرئيسية', 'مجمع سلمان الفارسي التعليمي - مدرسة إيرانية في دبي', 'مجمع سلمان الفارسي التعليمي، المدرسة الإيرانية في دبي، التعليم باللغة الفارسية في الإمارات، المدارس الإيرانية دبي، التعليم في دبي، التعليم الإيراني عالي الجودة، سلمان الفارسي دبي، المدرسة الإيرانية الإمارات العربية المتحدة', 'home', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(4, 2, 'fa', 'درباره ما', 'تاریخچه مجتمع آموزشی سلمان فارسی', 'تاریخچه مجتمع سلمان فارسی، مدرسه ایرانی دبی، پیشینه مجتمع سلمان فارسی، کادر آموزشی سلمان فارسی، مأموریت آموزشی، دیدگاه آموزشی، ارزش‌های سلمان فارسی، سابقه آموزشی، مدرسه فارسی‌زبان دبی', 'about', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(5, 2, 'en', 'About Us', 'History of Salman Farsi Educational Complex', 'Salman Farsi Complex history, Iranian school Dubai, background Salman Farsi Complex, Salman Farsi faculty, educational mission, educational vision, Salman Farsi values, educational history, Persian language school Dubai', 'about', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(6, 2, 'ar', 'من نحن', 'نبذة عن مجمع سلمان الفارسي التعليمي', 'تاريخ مجمع سلمان الفارسي، المدرسة الإيرانية دبي، خلفية مجمع سلمان الفارسي، هيئة التدريس بسلمان الفارسي، الرسالة التعليمية، الرؤية التعليمية، قيم سلمان الفارسي، التاريخ التعليمي، مدرسة اللغة الفارسية دبي', 'about', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(7, 3, 'fa', 'تقویم آموزشی', 'تقویم رویدادها و برنامه‌های آموزشی مجتمع سلمان فارسی', 'تقویم آموزشی سلمان فارسی، برنامه سال تحصیلی، تقویم رویدادهای مدرسه، تعطیلات مدرسه، تقویم امتحانات، برنامه‌های فوق برنامه، رویدادهای تحصیلی سلمان فارسی، جدول زمانی آموزشی', 'academic-calendar', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(8, 3, 'en', 'Academic Calendar', 'Calendar of events and educational programs at Salman Farsi Complex', 'Salman Farsi academic calendar, school year schedule, school events calendar, school holidays, exam calendar, extracurricular programs, Salman Farsi educational events, academic timetable', 'academic-calendar', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(9, 3, 'ar', 'التقويم الأكاديمي', 'تقويم الفعاليات والبرامج التعليمية في مجمع سلمان الفارسي', 'التقويم الأكاديمي سلمان الفارسي، جدول العام الدراسي، تقويم فعاليات المدرسة، العطل المدرسية، تقويم الامتحانات، البرامج اللامنهجية، الفعاليات التعليمية بسلمان الفارسي، الجدول الزمني الأكاديمي', 'academic-calendar', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(10, 4, 'fa', 'دستاوردها و افتخارات', 'دستاوردها و افتخارات دانش‌آموزان مجتمع آموزشی سلمان فارسی', 'دستاوردهای دانش‌آموزان سلمان فارسی، افتخارات مجتمع سلمان فارسی، جوایز علمی، موفقیت‌های تحصیلی، المپیادهای علمی، مسابقات دانش‌آموزی، افتخارات ورزشی، دستاوردهای هنری، افتخارآفرینان سلمان فارسی', 'achievements', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(11, 4, 'en', 'Achievements & Awards', 'Achievements and awards of Salman Farsi Educational Complex students', 'Salman Farsi student achievements, Salman Farsi Complex honors, academic awards, educational successes, scientific olympiads, student competitions, sports achievements, artistic accomplishments, Salman Farsi honorees', 'achievements', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(12, 4, 'ar', 'الإنجازات والجوائز', 'إنجازات وجوائز طلاب مجمع سلمان الفارسي التعليمي', 'إنجازات طلاب سلمان الفارسي، تكريمات مجمع سلمان الفارسي، الجوائز الأكاديمية، النجاحات التعليمية، الأولمبياد العلمية، مسابقات الطلاب، الإنجازات الرياضية، الإنجازات الفنية، المكرمون في سلمان الفارسي', 'achievements', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(13, 5, 'fa', 'اخبار و مقالات', 'آخرین اخبار و مقالات مجتمع آموزشی سلمان فارسی', 'اخبار مجتمع سلمان فارسی، رویدادهای مدرسه ایرانی دبی، آخرین اخبار آموزشی، اطلاعیه‌های مدرسه، فعالیت‌های دانش‌آموزی، رویدادهای فرهنگی، جشن‌های مدرسه، مناسبت‌های ملی و مذهبی، اخبار آموزشی امارات', 'blog', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(14, 5, 'en', 'News & Articles', 'Latest news and articles from Salman Farsi Educational Complex', 'Salman Farsi Complex news, Dubai Iranian school events, latest educational news, school announcements, student activities, cultural events, school celebrations, national and religious occasions, UAE educational news', 'blog', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
(15, 5, 'ar', 'الأخبار والمقالات', 'أحدث الأخبار والمقالات من مجمع سلمان الفارسي التعليمي', 'أخبار مجمع سلمان الفارسي، أحداث المدرسة الإيرانية دبي، أحدث الأخبار التعليمية، إعلانات المدرسة، أنشطة الطلاب، الفعاليات الثقافية، احتفالات المدرسة، المناسبات الوطنية والدينية، أخبار التعليم في الإمارات', 'blog', '2025-05-10 11:28:11', '2025-05-10 11:33:38'),
