DROP TABLE IF EXISTS `blog_content_view`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `blog_content_view`  AS SELECT `bc`.`content_id` AS `content_id`, `bc`.`post_id` AS `post_id`, `bc`.`field_key` AS `field_key`, `bc`.`content` AS `content`, `bt`.`language_id` AS `language_id`, `bc`.`section_id` AS `section_id`, `bc`.`sort_order` AS `sort_order`, `bc`.`is_repeatable` AS `is_repeatable`, `bc`.`is_active` AS `is_active`, `l`.`name` AS `language_name`, `l`.`is_rtl` AS `is_rtl`, `bt`.`content_value` AS `translated_content` FROM ((`temp_blog_content` `bc` left join `temp_blog_translations` `bt` on(`bc`.`content_id` = `bt`.`content_id`)) left join `core_languages` `l` on(`bt`.`language_id` = `l`.`code`)) ;

